1	// test_ebpf.cpp
2	// eBPF 功能专项测试
3	// 测试 BPF 程序加载、kprobe 挂载、流量数据采集
4	// 编译: g++ -std=c++17 -O2 -Wall -Iinclude -o test/test_ebpf test/test_ebpf.cpp src/net_traffic.cpp src/traffic_analyzer.cpp src/serializer.cpp src/net_info.cpp src/logger.cpp $(pkg-config --cflags --libs libbpf) -lglog -lbpf
