24	using namespace weaknet_dbus;
25	
26	// 测试结果统计
27	struct TestStats {
28	    int total = 0;
29	    int passed = 0;
30	    int failed = 0;
31	    
32	    void addResult(bool success, const std::string& testName) {
33	        total++;
34	        if (success) {
35	            passed++;
36	            std::cout << "  ✅ " << testName << std::endl;
37	        } else {
38	            failed++;
39	            std::cout << "  ❌ " << testName << std::endl;
40	        }
41	    }
42	    
43	    void print() {
44	        std::cout << "\n📊 测试统计: 总计=" << total 
45	                  << ", 通过=" << passed 
46	                  << ", 失败=" << failed 
47	                  << ", 成功率=" << (total > 0 ? (passed * 100.0 / total) : 0.0) << "%" << std::endl;
48	    }
49	};
50	
51	TestStats g_stats;
52	
53	// 探测并解析有效的 BPF 对象文件路径
54	static std::string resolveBpfObjectPath(const std::string& bpfName = "flow_rate.bpf.o") {
55	    const std::vector<std::string> candidatePaths = {
56	        "server/build/" + bpfName,
57	        "build/" + bpfName,
58	        "/home/radxa/weaknet/server/build/" + bpfName,
59	        "./" + bpfName
60	    };
61	    struct stat st;
62	    for (const auto& path : candidatePaths) {
63	        if (stat(path.c_str(), &st) == 0) {
64	            return path;
65	        }
66	    }
67	    return "server/build/" + bpfName;
68	}
69	
70	// 测试1: 检查 BPF 对象文件是否存在
71	bool testBpfObjectExists() {
72	    std::cout << "\n🧪 测试1: BPF 对象文件检查" << std::endl;
73	
74	    std::string bpfPath = resolveBpfObjectPath("flow_rate.bpf.o");
75	    struct stat st;
76	
77	    if (stat(bpfPath.c_str(), &st) == 0) {
78	        g_stats.addResult(true, "BPF 对象文件存在: " + bpfPath);
79	        std::cout << "     📦 文件大小: " << st.st_size << " 字节" << std::endl;
80	        return true;
81	    } else {
82	        g_stats.addResult(false, "BPF 对象文件不存在: " + bpfPath);
83	        return false;
84	    }
85	}
86	
87	// 测试2: 检查 libbpf 支持
88	bool testLibbpfSupport() {
89	    std::cout << "\n🧪 测试2: libbpf 支持检查" << std::endl;
90	    
91	    #if defined(__has_include)
92	    #  if __has_include(<linux/bpf.h>) && __has_include(<bpf/libbpf.h>) && __has_include(<bpf/bpf.h>)
93	        g_stats.addResult(true, "libbpf 头文件可用");
94	        return true;
95	    #  else
96	        g_stats.addResult(false, "libbpf 头文件不可用");
97	        return false;
98	    #  endif
99	    #else
100	        g_stats.addResult(false, "无法检查 libbpf 支持");
101	        return false;
