1	/**
2	 * @file tcp_retransmit_monitor.cpp
3	 * @brief TCP 重传追踪监控器 - 用户态实现
4	 *
5	 * 监控指标：
6	 *   - 每 TCP 连接的重传率：total_retrans / total_segs × 100%
7	 *   - 全局 TCP 重传率（computeLossRate）
8	 *   - 重传事件：含 pid/tgid/timestamp/tcp 状态
9	 *   - 顶 N 重传最多连接（getTopRetransConnections）
10	 *
11	 * 数据源（eBPF）：
12	 *   - BPF 对象文件名：tcp_retransmit.bpf.o
13	 *   - 探针类型：kprobe（内核函数入口）
14	 *     - kprobe/tcp_retransmit_skb → trace_tcp_retransmit（捕获 TCP 重传事件，更新 retrans_stats Map）
15	 *     - kprobe/tcp_sendmsg         → trace_tcp_sendmsg（捕获正常 TCP 发送，累计 total_segs）
16	 *   - 数据通道：BPF Map（Hash 类型）
17	 *     - retrans_events：重传事件 Map（键 = tcp_conn_key 四元组，值 = tcp_retrans_event{pid/timestamp/segs_out/segs_retrans/sstate}）
18	 *     - retrans_stats：重传统计 Map（键 = tcp_conn_key 四元组，值 = tcp_retrans_stats{total_retrans/total_segs/last_state}）
19	 *   - 用户态通过 bpf_map_get_next_key + bpf_map_lookup_elem 遍历 retrans_stats Map
20	 *
21	 * 线程模型：
22	 *   - 本类本身不创建独立线程，由外部周期性调用 getStats() / computeLossRate()
23	 *   - 无锁：eBPF Map 读取对并发安全
24	 *
25	 * 重传归因分析：
26	 *   - 重传率高 + TCP 状态为 CLOSE_WAIT → 对端问题（服务器没处理完就关了连接）
27	 *   - 重传率高 + TCP 状态为 ESTABLISHED → 链路问题（网络丢包）
28	 *   - 重传率高 + TCP 状态为 TIME_WAIT → 正常关闭的连接不应该有重传，检查异常
29	 */
30	
31	#include "tcp_retransmit_monitor.hpp"
32	#include "logger.hpp"
33	
34	#include <cstring>
35	#include <cstdio>
36	#include <sstream>
37	#include <algorithm>
38	#include <arpa/inet.h>
39	#include <chrono>
40	
41	#if defined(__has_include)
42	#  if __has_include(<linux/bpf.h>) && __has_include(<bpf/libbpf.h>) && __has_include(<bpf/bpf.h>)
43	#    define HAVE_LIBBPF 1
44	extern "C" {
45	#include <linux/bpf.h>
46	#include <bpf/libbpf.h>
47	#include <bpf/bpf.h>
48	#include <unistd.h>
49	}
50	#  else
51	#    define HAVE_LIBBPF 0
52	#  endif
53	#else
54	#  define HAVE_LIBBPF 0
55	#endif
56	
57	namespace weaknet_dbus {
58	
59	// ---- 数据结构映射（与 BPF 端 C 结构体一一对应） ----
60	
61	/**
62	 * @brief TCP 连接四元组键（与 BPF 端 retrans_events/retrans_stats Map 的 key 一致）
63	 */
64	struct tcp_conn_key {
65	    __u32 saddr;   // 源 IP（网络字节序）
66	    __u32 daddr;   // 目的 IP（网络字节序）
67	    __u16 sport;   // 源端口
68	    __u16 dport;   // 目的端口
69	} __attribute__((packed));
70	
71	/**
72	 * @brief TCP 重传事件记录（与 BPF 端 retrans_events Map 的 value 一致）
73	 */
74	struct tcp_retrans_event {
75	    __u32 pid;              // 进程 ID
76	    __u32 tgid;             // 线程组 ID（= pid）
77	    __u64 timestamp_ns;     // 事件时间戳（纳秒，CLOCK_MONOTONIC）
78	    __u32 segs_out;         // 该连接累计发送段数（来自 tcp_sock->segs_out）
79	    __u32 segs_retrans;     // 该连接累计重传段数（来自 tcp_sock->segs_retrans）
80	    __u32 sstate;           // TCP 连接状态（tcp_states 枚举：ESTABLISHED/TIME_WAIT/CLOSE_WAIT 等）
81	};
82	
83	/**
84	 * @brief TCP 重传统计（与 BPF 端 retrans_stats Map 的 value 一致）
85	 */
86	struct tcp_retrans_stats {
87	    __u64 total_retrans;   // 累计重传次数
88	    __u64 total_segs;      // 累计发送段数（正常发送 + 重传）
89	    __u32 last_state;      // 最后一次捕获时的 TCP 状态
90	};
91	
92	// ---- 辅助函数 ----
93	
94	/**
95	 * @brief 将 tcp_conn_key 格式化为可读字符串 "src:port -> dst:port"
96	 * @param key TCP 连接四元组键
97	 * @return 格式化后的字符串
98	 */
99	std::string connKeyToString(const tcp_conn_key& key) {
100	    struct in_addr sa{key.saddr}, da{key.daddr};
101	    char src_buf[INET_ADDRSTRLEN], dst_buf[INET_ADDRSTRLEN];
102	    inet_ntop(AF_INET, &sa, src_buf, sizeof(src_buf));
103	    inet_ntop(AF_INET, &da, dst_buf, sizeof(dst_buf));
104	    char buf[128];
105	    std::snprintf(buf, sizeof(buf), "%s:%u -> %s:%u",
106	        src_buf, ntohs(key.sport),
107	        dst_buf, ntohs(key.dport));
108	    return std::string(buf);
109	}
110	
111	/**
112	 * @brief TcpConnKey 比较运算符（用于 std::map 的有序排序）
113	 */
114	bool TcpConnKey::operator<(const TcpConnKey& other) const {
115	    if (saddr != other.saddr) return saddr < other.saddr;
116	    if (daddr != other.daddr) return daddr < other.daddr;
117	    if (sport != other.sport) return sport < other.sport;
118	    return dport < other.dport;
119	}
120	
121	bool TcpConnKey::operator==(const TcpConnKey& other) const {
122	    return saddr == other.saddr && daddr == other.daddr &&
123	           sport == other.sport && dport == other.dport;
124	}
125	
126	// ---- 实现 ----
127	
128	/**
129	 * @brief Pimpl 实现结构体
130	 */
131	struct TcpRetransMonitor::Impl {
132	    int retrans_events_fd = -1;  ///< retrans_events Map fd（重传事件明细）
133	    int retrans_stats_fd = -1;   ///< retrans_stats Map fd（重传统计聚合）
134	    uint32_t retrans_stats_max = 0;  ///< retrans_stats 的 resolved 容量（0=未知，不计水位）
135	    struct bpf_object *obj = nullptr;
136	    struct bpf_link *link_retrans = nullptr;  ///< kprobe/tcp_retransmit_skb BPF link（捕获重传）
137	    struct bpf_link *link_send = nullptr;     ///< kprobe/tcp_sendmsg BPF link（正常发送，用于累计 total_segs）
138	};
139	
140	TcpRetransMonitor::TcpRetransMonitor()
141	    : impl_(std::make_unique<Impl>()) {}
142	
143	TcpRetransMonitor::~TcpRetransMonitor() {
144	    stop();
145	}
146	
147	/**
148	 * @brief 初始化 TCP 重传监控器
149	 *
150	 * 挂载 2 个 kprobe：
151	 *   - kprobe/tcp_retransmit_skb → trace_tcp_retransmit（捕获重传事件，更新 total_retrans）
152	 *   - kprobe/tcp_sendmsg         → trace_tcp_sendmsg（捕获正常 TCP 发送，更新 total_segs）
153	 *
154	 * @param bpfObjPath BPF 对象文件路径（通常为 "build/tcp_retransmit.bpf.o"）
155	 * @return true  初始化成功（至少一个 kprobe 挂载成功）
156	 *         false 初始化失败
157	 */
158	bool TcpRetransMonitor::init(const std::string& bpfObjPath, const weaknet::MapSizingPlan& plan) {
159	    stateSupport_.setState(EbpfMonitorState::Initializing, false, "loading BPF object");
160	#if !HAVE_LIBBPF
161	    LOG_INFO(LogModule::TCP_LOSS, "TcpRetransMonitor: BPF not available (no libbpf)");
162	    available_ = false;
163	    initialized_ = true;
164	    stateSupport_.setState(EbpfMonitorState::Fallback, false, "libbpf unavailable");
165	    return false;
166	#else
167	    LOG_INFO(LogModule::TCP_LOSS, "TcpRetransMonitor: loading BPF object from " << bpfObjPath);
168	
169	    // 打开 BPF 对象
170	    LIBBPF_OPTS(bpf_object_open_opts, opts);
171	    struct bpf_object *obj = bpf_object__open_file(bpfObjPath.c_str(), &opts);
172	    if (!obj) {
173	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: failed to open BPF object: " << bpfObjPath);
174	        available_ = false;
175	        initialized_ = true;
176	        stateSupport_.setState(EbpfMonitorState::Error, false, "failed to open BPF object");
177	        return false;
178	    }
179	
180	    // 加载 BPF 程序到内核
181	    // 在 open→load 间隙应用容量定标：map 一旦 load 就无法 resize。
182	    weaknet::applyMapSizingPlan(obj, plan);
183	    impl_->retrans_stats_max = weaknet::findResolvedMax(plan, "retrans_stats");
184	
185	    if (bpf_object__load(obj) != 0) {
186	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: failed to load BPF object");
187	        bpf_object__close(obj);
188	        available_ = false;
189	        initialized_ = true;
190	        stateSupport_.setState(EbpfMonitorState::Error, false, "failed to load BPF object");
191	        return false;
192	    }
193	
194	    // 查找 retrans_events Map（重传事件明细）和 retrans_stats Map（重传统计聚合）
195	    impl_->retrans_events_fd = bpf_object__find_map_fd_by_name(obj, "retrans_events");
196	    if (impl_->retrans_events_fd < 0) {
197	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: retrans_events map not found");
198	        bpf_object__close(obj);
199	        available_ = false;
200	        initialized_ = true;
201	        stateSupport_.setState(EbpfMonitorState::Error, false, "retrans_events map not found");
202	        return false;
203	    }
204	
205	    impl_->retrans_stats_fd = bpf_object__find_map_fd_by_name(obj, "retrans_stats");
206	    if (impl_->retrans_stats_fd < 0) {
207	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: retrans_stats map not found");
208	        bpf_object__close(obj);
209	        available_ = false;
210	        initialized_ = true;
211	        stateSupport_.setState(EbpfMonitorState::Error, false, "retrans_stats map not found");
212	        return false;
213	    }
214	
215	    // 排除服务端自身（主动探测）连接的 TCP 重传。
216	    // 本探针的统计直接参与 Reliability SLE（blocking Core SLE），
217	    // 探测流量进入会同时污染 Active/Passive 边界与 Overall 判决。
218	    // 灌入 PID 后，sendmsg 侧据此登记 socket cookie，
219	    // 供 retransmit 侧在 softirq 上下文（PID 不可用）识别。
220	    {
221	        const int self_fd = bpf_object__find_map_fd_by_name(obj, "retrans_self_pid");
222	        if (self_fd >= 0) {
223	            __u32 k = 0;
224	            __u32 self_pid = static_cast<__u32>(::getpid());
225	            if (bpf_map_update_elem(self_fd, &k, &self_pid, BPF_ANY) == 0) {
226	                LOG_INFO(LogModule::TCP_LOSS,
227	                         "TcpRetransMonitor: self-pid filter set to " << self_pid);
228	            }
229	        }
230	    }
231	
232	    // attach 探针到 kprobe/tcp_retransmit_skb 和 kprobe/tcp_sendmsg
233	    // 前者捕获重传事件，后者用于累计总发送段数（分母）
234	    struct bpf_program *retrans_prog = bpf_object__find_program_by_name(obj, "trace_tcp_retransmit");
235	    struct bpf_program *send_prog = bpf_object__find_program_by_name(obj, "trace_tcp_sendmsg");
236	    if (!retrans_prog || !send_prog) {
237	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: BPF program not found");
238	        bpf_object__close(obj);
239	        available_ = false;
240	        initialized_ = true;
241	        stateSupport_.setState(EbpfMonitorState::Error, false, "BPF program not found");
242	        return false;
243	    }
244	
245	    impl_->link_retrans = bpf_program__attach(retrans_prog);
246	    if (libbpf_get_error(impl_->link_retrans)) {
247	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: attach tcp_retransmit_skb failed");
248	        impl_->link_retrans = nullptr;
249	    }
250	    impl_->link_send = bpf_program__attach(send_prog);
251	    if (libbpf_get_error(impl_->link_send)) {
252	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: attach tcp_sendmsg failed");
253	        impl_->link_send = nullptr;
254	    }
255	
256	    if (!impl_->link_retrans && !impl_->link_send) {
257	        LOG_ERROR(LogModule::TCP_LOSS, "TcpRetransMonitor: both probes failed to attach");
258	        bpf_object__close(obj);
259	        impl_->link_retrans = impl_->link_send = nullptr;
260	        available_ = false;
261	        initialized_ = true;
262	        stateSupport_.setState(EbpfMonitorState::Fallback, false, "all BPF probes failed to attach");
263	        return false;
264	    }
265	
266	    impl_->obj = obj;
267	    available_ = true;
268	    initialized_ = true;
269	
270	    LOG_INFO(LogModule::TCP_LOSS, "TcpRetransMonitor: initialized successfully");
271	    stateSupport_.setState(EbpfMonitorState::Attached, true, "BPF probes attached");
272	    stateSupport_.recordProbeAttached();
273	    stateSupport_.recordProbeAttached();
274	    return true;
275	#endif
276	}
277	
278	/**
279	 * @brief 停止 TCP 重传监控器：销毁 BPF link 和 BPF 对象
280	 */
281	void TcpRetransMonitor::stop() {
282	    stateSupport_.setState(EbpfMonitorState::Stopped, false, "stopped");
283	#if HAVE_LIBBPF
284	    if (impl_->link_retrans) { bpf_link__destroy(impl_->link_retrans); impl_->link_retrans = nullptr; }
285	    if (impl_->link_send) { bpf_link__destroy(impl_->link_send); impl_->link_send = nullptr; }
286	#endif
287	    if (impl_->obj) {
288	        bpf_object__close(impl_->obj);
289	        impl_->obj = nullptr;
290	        LOG_INFO(LogModule::TCP_LOSS, "TcpRetransMonitor: stopped");
291	    }
292	    impl_->retrans_events_fd = -1;
293	    impl_->retrans_stats_fd = -1;
294	    available_ = false;
295	}
296	
297	/**
298	 * @brief 从 retrans_stats Map 获取所有连接的重传统计
299	 *
300	 * 遍历 retrans_stats Map，将内核态 tcp_conn_key + tcp_retrans_stats
301	 * 转为用户态 TcpConnKey + TcpRetransStats 结构。
302	 *
303	 * @return 以 TcpConnKey 为键的重传统计 Map
304	 */
305	std::map<TcpConnKey, TcpRetransStats> TcpRetransMonitor::getStats() {
306	    std::map<TcpConnKey, TcpRetransStats> result;
307	#if HAVE_LIBBPF
308	    if (impl_->retrans_stats_fd < 0) {
309	        stateSupport_.recordReadFailure("retrans_stats map unavailable");
310	        return result;
311	    }
312	
313	    auto started = std::chrono::steady_clock::now();
314	    // 逐 key 差分快照：key 为连接四元组，累计值取 total_segs（单调不减，除非被驱逐重建）
315	    std::vector<std::pair<std::string, uint64_t>> key_snapshot;
316	    // 遍历 retrans_stats Map（Hash 类型，逐 key 遍历）
317	    tcp_conn_key cur_key = {}, next_key = {};
318	    while (bpf_map_get_next_key(impl_->retrans_stats_fd, &cur_key, &next_key) == 0) {
319	        tcp_retrans_stats stats = {};
320	        if (bpf_map_lookup_elem(impl_->retrans_stats_fd, &next_key, &stats) == 0) {
321	            TcpConnKey key{next_key.saddr, next_key.daddr, next_key.sport, next_key.dport};
322	            TcpRetransStats val{stats.total_retrans, stats.total_segs, stats.last_state};
323	            result[key] = val;
324	            // 用四元组原文构造稳定 key（不依赖格式化，避免展示层变更影响差分）
325	            key_snapshot.emplace_back(
326	                std::string(reinterpret_cast<const char*>(&next_key), sizeof(next_key)),
327	                static_cast<uint64_t>(stats.total_segs));
328	        }
329	        cur_key = next_key;
330	    }
331	    // 更新驱逐可见性差分的基线快照。
332	    // key_tracker_ 非线程安全：虽当前仅 worker 线程调用，仍统一在
333	    // key_stats_mutex_ 临界区内 update()，与其它三个监控器保持同一约定。
334	    {
335	        std::lock_guard<std::mutex> lock(key_stats_mutex_);
336	        key_stats_ = key_tracker_.update(key_snapshot, impl_->retrans_stats_max);
337	    }
338	    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(
339	        std::chrono::steady_clock::now() - started).count();
340	    stateSupport_.recordReadSuccess(static_cast<uint64_t>(elapsed), !result.empty());
341	#endif
342	    return result;
343	}
344	
345	/**
346	 * @brief 计算全局 TCP 重传率
347	 *
348	 * 将所有连接的 total_retrans 和 total_segs 分别累加，
349	 * 然后计算加权重传率（避免单连接 total_segs 为 0 导致的除零问题）。
350	 *
351	 * 计算公式：lossRate = Σ(total_retrans) / Σ(total_segs) × 100%
352	 *
353	 * @return 全局 TCP 重传率（%）；无数据时返回 0.0
354	 */
355	double TcpRetransMonitor::computeLossRate() {
356	    auto stats = getStats();
357	    uint64_t totalRetrans = 0, totalSegs = 0;
358	    for (const auto& [key, val] : stats) {
359	        totalRetrans += val.totalRetrans;  // 累加所有连接的重传次数
360	        totalSegs += val.totalSegs;        // 累加所有连接的发送段数
361	    }
362	    if (totalSegs == 0) return 0.0;         // 无流量时返回 0
363	    return (totalRetrans * 100.0) / totalSegs;  // 重传率 = 重传次数 / 总段数 × 100%
364	}
365	
366	/**
367	 * @brief 获取顶 N 重传最多的连接（按 totalRetrans 降序）
368	 *
369	 * @param topN 返回的最大连接数
370	 * @return 按重传次数降序排列的连接统计列表
371	 */
372	std::vector<std::pair<TcpConnKey, TcpRetransStats>> TcpRetransMonitor::getTopRetransConnections(size_t topN) {
373	    auto stats = getStats();
374	    std::vector<std::pair<TcpConnKey, TcpRetransStats>> vec(stats.begin(), stats.end());
375	    std::sort(vec.begin(), vec.end(),
376	        [](const auto& a, const auto& b) {
377	            return a.second.totalRetrans > b.second.totalRetrans;  // 按重传次数降序
378	        });
379	    if (vec.size() > topN) vec.resize(topN);
380	    return vec;
381	}
382	
383	}  // namespace weaknet_dbus
384

