53	// ---- 数据结构映射（与 BPF 端 C 结构体一一对应，必须保持字段一致） ----
54	
55	/**
56	 * @brief 全局聚合统计（与 BPF 端 conn_stats Map 的 value 一致）
57	 */
58	struct tcp_conn_global {
59	    int64_t total_accepts;         // 累计入向连接 accept 数
60	    uint64_t total_accept_failures; // accept 返回错误指针次数
61	    uint64_t accepts_v4;           // IPv4 入向连接数
62	    uint64_t accepts_v6;           // IPv6 入向连接数
63	    uint64_t total_closes;         // 累计被跟踪入向连接关闭数
64	    int64_t active_inbound;        // 当前活跃入向连接数
65	    uint64_t total_duration_ns;    // 已关闭连接时长总和
66	    uint64_t max_duration_ns;      // 已关闭连接最大时长
67	    uint64_t duration_count;       // 已完成时长统计的连接数
68	    uint64_t hist[7];              // 连接时长分桶计数
69	};
