72	 * @brief 每端口 accept/close 计数（与 BPF 端 conn_ports Map 的 value 一致）
73	 */
74	struct tcp_conn_port_value {
75	    uint64_t accepts;
76	    uint64_t closes;
77	};
78	
79	// conn_ports 遍历的安全上限（map max_entries=128，防御异常返回导致死循环）
80	constexpr int kPortIterMax = 128;
81	// getStats 输出的端口明细上限（按 accept 数降序截断）
82	constexpr size_t kTopPortsMax = 8;
83	
84	}  // namespace
