87	
88	/**
89	 * @brief Pimpl 实现结构体，持有 libbpf 句柄
90	 *
91	 * 采用 Pimpl 模式隔离 libbpf 依赖，避免在没有 libbpf 的编译环境中暴露 BPF 类型
92	 */
93	struct TcpConnMonitor::Impl {
94	    int conn_start_fd = -1;            ///< conn_start Map fd（连接起始时间）
95	    int conn_stats_fd = -1;            ///< conn_stats Map fd（全局聚合）
96	    int conn_ports_fd = -1;            ///< conn_ports Map fd（每端口计数）
97	    struct bpf_object *obj = nullptr;  ///< BPF 对象实例
98	    struct bpf_link *link_accept = nullptr;  ///< kretprobe/inet_csk_accept 的 BPF link
99	    struct bpf_link *link_close = nullptr;   ///< kprobe/tcp_close 的 BPF link
100	};
101	
102	TcpConnMonitor::TcpConnMonitor() : impl_(std::make_unique<Impl>()) {}
103	TcpConnMonitor::~TcpConnMonitor() { stop(); }
104	
105	/**
106	 * @brief 初始化：加载 BPF 对象、查找 map/程序、挂载探针、预创建聚合条目
107	 *
108	 * 初始化流程：
109	 *   1. 打开并加载 BPF 对象文件（tcp_conn_stats.bpf.o）
110	 *   2. 查找 3 个 Map 的 fd：conn_start / conn_stats / conn_ports
111	 *   3. 找到 2 个 BPF 程序：trace_inet_csk_accept / trace_tcp_close
112	 *   4. attach 两个探针（libbpf 根据 SEC 名自动选择 kprobe/kretprobe）
113	 *   5. 预创建 conn_stats 的 key=0 聚合条目（BPF 侧虽也有 lookup-or-create，
114	 *      但预创建保证 getStats() 在空闲期读取零值而不是 ENOENT）
115	 *
116	 * @param bpfObjPath BPF 对象文件路径
117	 * @return true  初始化成功（两个探针均挂载）
118	 *         false 初始化失败
119	 */
120	bool TcpConnMonitor::init(const std::string& bpfObjPath, const weaknet::MapSizingPlan& plan) {
121	    stateSupport_.setState(EbpfMonitorState::Initializing, false, "loading BPF object");
122	#if !HAVE_LIBBPF
123	    LOG_INFO(LogModule::TCP_LOSS, "TcpConnMonitor: BPF not available (no libbpf)");
124	    available_ = false;
125	    initialized_ = true;
126	    stateSupport_.setState(EbpfMonitorState::Fallback, false, "libbpf unavailable");
127	    return false;
128	#else
129	    LOG_INFO(LogModule::TCP_LOSS, "TcpConnMonitor: loading BPF object from " << bpfObjPath);
130	
131	    LIBBPF_OPTS(bpf_object_open_opts, opts);
132	    struct bpf_object *obj = bpf_object__open_file(bpfObjPath.c_str(), &opts);
133	    if (!obj) {
134	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: failed to open BPF object: " << bpfObjPath);
135	        available_ = false;
136	        initialized_ = true;
137	        stateSupport_.setState(EbpfMonitorState::Error, false, "failed to open BPF object");
138	        return false;
139	    }
140	
141	    // 在 open→load 间隙应用容量定标：map 一旦 load 就无法 resize。
142	
143	    weaknet::applyMapSizingPlan(obj, plan);
144	
145	
146	    if (bpf_object__load(obj) != 0) {
147	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: failed to load BPF object");
148	        bpf_object__close(obj);
149	        available_ = false;
150	        initialized_ = true;
151	        stateSupport_.setState(EbpfMonitorState::Error, false, "failed to load BPF object");
152	        return false;
153	    }
154	
155	    impl_->conn_start_fd = bpf_object__find_map_fd_by_name(obj, "conn_start");
156	    if (impl_->conn_start_fd < 0) {
157	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: conn_start map not found");
158	        bpf_object__close(obj);
159	        available_ = false;
160	        initialized_ = true;
161	        stateSupport_.setState(EbpfMonitorState::Error, false, "conn_start map not found");
162	        return false;
163	    }
164	
165	    impl_->conn_stats_fd = bpf_object__find_map_fd_by_name(obj, "conn_stats");
166	    if (impl_->conn_stats_fd < 0) {
167	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: conn_stats map not found");
168	        bpf_object__close(obj);
169	        available_ = false;
170	        initialized_ = true;
171	        stateSupport_.setState(EbpfMonitorState::Error, false, "conn_stats map not found");
172	        return false;
173	    }
174	
175	    impl_->conn_ports_fd = bpf_object__find_map_fd_by_name(obj, "conn_ports");
176	    if (impl_->conn_ports_fd < 0) {
177	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: conn_ports map not found");
178	        bpf_object__close(obj);
179	        available_ = false;
180	        initialized_ = true;
181	        stateSupport_.setState(EbpfMonitorState::Error, false, "conn_ports map not found");
182	        return false;
183	    }
184	
185	    struct bpf_program *accept_prog = bpf_object__find_program_by_name(obj, "trace_inet_csk_accept");
186	    struct bpf_program *close_prog = bpf_object__find_program_by_name(obj, "trace_tcp_close");
187	    if (!accept_prog || !close_prog) {
188	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: BPF program not found"
189	                  << (!accept_prog ? " trace_inet_csk_accept" : "")
190	                  << (!close_prog ? " trace_tcp_close" : ""));
191	        bpf_object__close(obj);
192	        available_ = false;
193	        initialized_ = true;
194	        stateSupport_.setState(EbpfMonitorState::Error, false, "BPF program not found");
195	        return false;
196	    }
197	
198	    // attach：libbpf 根据 SEC 名（kretprobe/kprobe）自动选择挂载方式
199	    impl_->link_accept = bpf_program__attach(accept_prog);
200	    long err_accept = libbpf_get_error(impl_->link_accept);
201	    if (err_accept) {
202	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: attach inet_csk_accept failed err=" << err_accept);
203	        impl_->link_accept = nullptr;
204	    }
205	
206	    impl_->link_close = bpf_program__attach(close_prog);
207	    long err_close = libbpf_get_error(impl_->link_close);
208	    if (err_close) {
209	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: attach tcp_close failed err=" << err_close);
210	        impl_->link_close = nullptr;
211	    }
212	
213	    if (!impl_->link_accept && !impl_->link_close) {
214	        LOG_ERROR(LogModule::TCP_LOSS, "TcpConnMonitor: both probes failed to attach");
215	        bpf_object__close(obj);
216	        available_ = false;
217	        initialized_ = true;
218	        stateSupport_.setState(EbpfMonitorState::Fallback, false, "all BPF probes failed to attach");
219	        return false;
220	    }
221	
222	    impl_->obj = obj;
223	    available_ = true;
224	    initialized_ = true;
225	
226	    // 预创建 conn_stats 的 key=0 聚合条目：BPF 侧虽有 lookup-or-create，
227	    // 但预创建保证空闲期 getStats() 读到零值而不是 ENOENT（DnsMonitor 的教训）
228	    {
229	        __u32 zero_key = 0;
230	        tcp_conn_global empty_record = {};
231	        if (bpf_map_update_elem(impl_->conn_stats_fd, &zero_key, &empty_record, BPF_ANY) != 0) {
232	            LOG_WARNING(LogModule::TCP_LOSS,
233	                        "TcpConnMonitor: pre-create conn_stats entry failed (errno=" << errno
234	                        << "), getStats will treat ENOENT as empty stats");
235	        }
236	    }
237	
238	    LOG_INFO(LogModule::TCP_LOSS, "TcpConnMonitor: initialized successfully");
239	    stateSupport_.setState(EbpfMonitorState::Attached, true, "BPF probes attached");
240	    stateSupport_.recordProbeAttached();
241	    stateSupport_.recordProbeAttached();
242	    return true;
243	#endif
244	}
245	
246	/**
247	 * @brief 读取 TCP 连接生命周期聚合统计
248	 *
249	 * 读取流程：
250	 *   1. bpf_map_lookup_elem 查询 conn_stats key=0 的全局聚合条目
251	 *   2. bpf_map_get_next_key 遍历 conn_ports（上限 128 次），收集每端口计数
252	 *   3. 时长纳秒转毫秒，端口表按 accept 数降序取前 8
253	 *
254	 * @return TcpConnAggStats 聚合统计结果；失败时返回零值结构体
255	 */
256	TcpConnAggStats TcpConnMonitor::getStats() {
257	    TcpConnAggStats result = {};
258	#if HAVE_LIBBPF
259	    if (!available_ || impl_->conn_stats_fd < 0)
260	        return result;
261	
262	    auto started = std::chrono::steady_clock::now();
263	    bool ok = false;
264	
265	    __u32 key = 0;
266	    tcp_conn_global stats = {};
267	    if (bpf_map_lookup_elem(impl_->conn_stats_fd, &key, &stats) == 0) {
268	        ok = true;
269	        result.totalAccepts = static_cast<uint64_t>(stats.total_accepts);
270	        result.totalAcceptFailures = stats.total_accept_failures;
271	        result.acceptsV4 = stats.accepts_v4;
272	        result.acceptsV6 = stats.accepts_v6;
273	        result.totalCloses = stats.total_closes;
274	        result.activeInbound = stats.active_inbound;
275	        result.durationCount = stats.duration_count;
276	        for (int i = 0; i < kTcpConnHistBuckets; ++i)
277	            result.hist[i] = stats.hist[i];
278	
279	        result.avgDurationMs = (stats.duration_count > 0)
280	            ? static_cast<uint64_t>(stats.total_duration_ns / stats.duration_count / 1000000)
281	            : 0;
282	        result.maxDurationMs = stats.max_duration_ns / 1000000;
283	
284	        // 遍历每端口计数表（get_next_key + lookup；上限防御异常返回）
285	        std::vector<TcpConnPortStats> ports;
286	        __u16 port_key = 0, next_key = 0;
287	        for (int i = 0; i < kPortIterMax; ++i) {
288	            if (bpf_map_get_next_key(impl_->conn_ports_fd, &port_key, &next_key) != 0)
289	                break;
290	            tcp_conn_port_value pv = {};
291	            if (bpf_map_lookup_elem(impl_->conn_ports_fd, &next_key, &pv) == 0) {
292	                ports.push_back(TcpConnPortStats{next_key, pv.accepts, pv.closes});
293	            }
294	            port_key = next_key;
295	        }
296	        std::sort(ports.begin(), ports.end(),
297	                  [](const TcpConnPortStats& a, const TcpConnPortStats& b) {
298	                      return a.accepts > b.accepts;
299	                  });
300	        if (ports.size() > kTopPortsMax)
301	            ports.resize(kTopPortsMax);
302	        result.topPorts = std::move(ports);
303	    } else if (errno == ENOENT) {
304	        // 聚合条目尚未创建（理论上 init 已预创建；此处兜底）——“暂无数据”
305	        // 不是监控故障，记为一次成功读取并返回零值
306	        ok = true;
307	    }
308	
309	    auto elapsed = std::chrono::duration_cast<std::chrono::microseconds>(
310	        std::chrono::steady_clock::now() - started).count();
311	    if (ok) {
312	        stateSupport_.recordReadSuccess(static_cast<uint64_t>(elapsed));
313	    } else {
314	        stateSupport_.recordReadFailure("conn_stats map lookup failed");
315	    }
316	#endif
317	    return result;
318	}
319	
320	/**
321	 * @brief 停止 TCP 连接监控器：销毁 BPF link 和 BPF 对象
322	 *
323	 * 释放所有 libbpf 资源，将状态置为 Stopped，available 置为 false
324	 */
325	void TcpConnMonitor::stop() {
326	    stateSupport_.setState(EbpfMonitorState::Stopped, false, "stopped");
327	#if HAVE_LIBBPF
328	    if (impl_->link_accept) { bpf_link__destroy(impl_->link_accept); impl_->link_accept = nullptr; }
329	    if (impl_->link_close) { bpf_link__destroy(impl_->link_close); impl_->link_close = nullptr; }
330	    if (impl_->obj) { bpf_object__close(impl_->obj); impl_->obj = nullptr; }
331	    impl_->conn_start_fd = impl_->conn_stats_fd = impl_->conn_ports_fd = -1;
332	    available_ = false;
333	#endif
334	}
335	
336	}  // namespace weaknet_dbus
