        json << "\"" << key << "\":{";
        json << "\"state\":\"" << healthStateToString(sle.state) << "\",";
        json << "\"coverage\":\"" << coverageToString(sle.coverage) << "\",";
        json << "\"applicability\":\"" << applicabilityToString(sle.applicability) << "\",";
